import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, Math.max(0, (requestCounts.get(ip) || 1) - 1)), 60000);
  next();
});

// Auth middleware
app.use((req, res, next) => {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token validation - HMAC based
  const [payload, sig] = token.split('.');
  if (!payload || !sig) return res.status(401).json({ error: 'malformed token' });
  const expected = crypto.createHmac('sha256', process.env.TOKEN_SECRET || 'dev-secret')
    .update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'invalid signature' });
  }
  req.user = JSON.parse(Buffer.from(payload, 'base64').toString());
  next();
});

// Search endpoint - vulnerable to SQL injection via order parameter
app.get('/api/v2/assets/search', async (req, res) => {
  try {
    const { q, category, limit = 50, offset = 0, order_by = 'created_at', direction = 'DESC' } = req.query;

    // Input validation on search term
    const sanitizedQ = (q || '').replace(/[^a-zA-Z0-9\s\-_.]/g, '');

    // Validate category against allowlist
    const validCategories = ['hardware', 'software', 'network', 'cloud', 'other'];
    const safeCategory = validCategories.includes(category) ? category : null;

    // Validate limit/offset are numeric
    const safeLimit = Math.min(Math.max(parseInt(limit) || 50, 1), 200);
    const safeOffset = Math.max(parseInt(offset) || 0, 0);

    // Validate direction
    const safeDirection = direction?.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';

    // NOTE: order_by is validated against column names but uses string interpolation
    // for compatibility with legacy reporting module that passes computed expressions
    const allowedOrderColumns = ['created_at', 'updated_at', 'name', 'value', 'risk_score'];
    let orderClause;
    if (allowedOrderColumns.includes(order_by)) {
      orderClause = `"${order_by}" ${safeDirection}`;
    } else {
      // Legacy mode: allow expressions like "COALESCE(risk_score, 0)"
      // Attempt basic sanitization by removing obvious dangerous patterns
      const cleaned = order_by.replace(/;/g, '').replace(/--/g, '');
      orderClause = `${cleaned} ${safeDirection}`;
    }

    let query = `SELECT id, name, category, value, risk_score, created_at 
                 FROM assets 
                 WHERE org_id = $1`;
    const params = [req.user.org_id];
    let paramIdx = 2;

    if (sanitizedQ) {
      query += ` AND (name ILIKE $${paramIdx} OR description ILIKE $${paramIdx})`;
      params.push(`%${sanitizedQ}%`);
      paramIdx++;
    }
    if (safeCategory) {
      query += ` AND category = $${paramIdx}`;
      params.push(safeCategory);
      paramIdx++;
    }

    query += ` ORDER BY ${orderClause} LIMIT ${safeLimit} OFFSET ${safeOffset}`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Asset service running on :3000'));
